// Builds the PDF report's HTML from the API response.
const res = $input.first().json;
const jobs = [...(res.items || [])].sort((a, b) => String(b.postedAt).localeCompare(String(a.postedAt)));
const TZ = 'Europe/Madrid';
const today = DateTime.now().setZone(TZ).toISODate();

const e = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const k = n => (n == null ? '?' : '€' + Math.round(n / 1000) + 'k');
const salary = s => !s || (s.min == null && s.max == null) ? 'Salary not stated'
  : (s.min === s.max || s.max == null ? k(s.min) : `${k(s.min)} – ${k(s.max)}`) + (s.period && s.period !== 'year' ? ` / ${s.period}` : '');
const when = iso => iso ? DateTime.fromISO(iso, { zone: 'utc' }).setZone(TZ).toFormat('d LLL, HH:mm') : '';
const cap = s => s ? String(s).charAt(0).toUpperCase() + String(s).slice(1) : '';
const exp = j => j.experienceYearsMin != null
  ? (j.experienceYearsMax != null ? `${j.experienceYearsMin}–${j.experienceYearsMax} yrs` : `${j.experienceYearsMin}+ yrs`) : '';

const cards = jobs.map(j => {
  const meta = [
    e(j.location),
    cap(j.workMode) + (j.remoteScope ? ` (${e(j.remoteScope)})` : ''),
    cap(j.seniority),
    e(j.roleFamily),
    exp(j),
    j.scheduleType ? e(j.scheduleType) : '',
  ].filter(Boolean).join(' · ');
  const flags = [
    j.visaSponsorship?.offered ? '<span class="flag ok">Visa sponsorship</span>' : '',
    j.relocationSupport && j.relocationSupport !== 'none' ? `<span class="flag ok">Relocation: ${e(j.relocationSupport)}</span>` : '',
    j.spanishRequirement === 'none' ? '<span class="flag">No Spanish needed</span>'
      : j.spanishRequirement ? `<span class="flag">Spanish: ${e(j.spanishRequirement)}</span>` : '',
    j.company?.isAgency ? '<span class="flag warn">Agency</span>' : '',
  ].join('');
  const tags = (j.tags || []).map(t => `<span>${e(t)}</span>`).join('');
  return `
  <div class="job">
    <div class="head">
      <div>
        <h2><a href="${e(j.url)}">${e(j.title)}</a></h2>
        <div class="co">${e(j.company?.name)} <span class="posted">· posted ${e(when(j.postedAt))}</span></div>
      </div>
      <div class="sal">${e(salary(j.salary))}</div>
    </div>
    <div class="meta">${meta}</div>
    ${flags ? `<div class="flags">${flags}</div>` : ''}
    ${tags ? `<div class="tags">${tags}</div>` : ''}
    ${j.snippet ? `<p>${e(j.snippet)}</p>` : ''}
  </div>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>SpainJobs report ${today}</title>
<style>
  @page { size: A4; margin: 16mm 14mm; }
  body { font-family: -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; color: #1a1a1a; font-size: 11pt; }
  h1 { font-size: 20pt; margin: 0 0 4px; }
  .sub { color: #666; margin-bottom: 18px; font-size: 10pt; }
  .job { border: 1px solid #ddd; border-radius: 8px; padding: 12px 14px; margin-bottom: 10px; page-break-inside: avoid; }
  .head { display: flex; justify-content: space-between; gap: 12px; }
  h2 { font-size: 13pt; margin: 0; } h2 a { color: #1a1a1a; text-decoration: none; }
  .co { color: #444; font-weight: 600; margin-top: 2px; } .posted { font-weight: 400; color: #777; }
  .sal { font-weight: 600; white-space: nowrap; }
  .meta { color: #666; font-size: 10pt; margin: 6px 0; }
  .flags .flag { display: inline-block; border: 1px solid #ccc; border-radius: 10px; padding: 0 8px; margin: 0 4px 4px 0; font-size: 9pt; color: #444; }
  .flags .ok { border-color: #86c79a; color: #1d6b35; } .flags .warn { border-color: #e0b36b; color: #8a5a00; }
  .tags span { display: inline-block; background: #eef2ff; color: #3730a3; border-radius: 10px; padding: 1px 8px; margin: 0 4px 4px 0; font-size: 9pt; }
  p { margin: 6px 0 0; font-size: 10pt; line-height: 1.4; color: #333; }
</style></head><body>
<h1>SpainJobs: remote engineering jobs</h1>
<div class="sub">Report of ${e(today)} · ${jobs.length} job${jobs.length === 1 ? '' : 's'}
  · filters: ${e([...(res.filters?.upstream || []), ...(res.filters?.local || [])].join(', '))}
  · data fetched ${e(when(res.source?.fetchedAt))}</div>
${cards || '<p>No jobs matched.</p>'}
</body></html>`;

return [{ json: { date: today, count: jobs.length, html } }];
